const express = require("express");
const helmet = require("helmet");
const cors = require("cors");
const rateLimit = require("express-rate-limit");

// Validate that required environment variables are set
const requiredEnvVars = ["SESSION_SECRET", "JWT_SECRET"];
if (process.env.NODE_ENV === "production") {
  requiredEnvVars.push("DATABASE_URL");
}

requiredEnvVars.forEach((envVar) => {
  if (!process.env[envVar]) {
    console.error(`\x1b[31mERROR: Missing required environment variable: ${envVar}\x1b[0m`);
    process.exit(1);
  }
});

const app = express();

// Security middleware
app.use(helmet());
app.disable("x-powered-by");

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? 
    process.env.ALLOWED_ORIGINS.split(",") : 
    ["http://localhost:3000", "http://localhost:3001"],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.NODE_ENV === "production" ? 100 : 1000, // limit each IP
  message: "Too many requests from this IP, please try again later."
});
app.use(limiter);

// Basic request logging and validation
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Health check endpoint
app.get("/health", (req, res) => {
  res.json({ 
    status: "ok", 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || "development"
  });
});

// Users endpoint - in real app, this would connect to database
app.get("/users", (req, res) => {
  // In production, this would query the database using DATABASE_URL
  res.json([
    { id: 1, name: "Alice", email: "alice@example.com" },
    { id: 2, name: "Bob", email: "bob@example.com" },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: "Something went wrong!",
    ...(process.env.NODE_ENV === "development" && { details: err.message })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: "Route not found" });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`\x1b[32mServer running in ${process.env.NODE_ENV || "development"} mode on port ${PORT}\x1b[0m`);
  if (process.env.NODE_ENV !== "production") {
    console.log(`\x1b[33mWarning: Running in development mode with reduced security\x1b[0m`);
  }
});

module.exports = app;' > app-secure-env.js

