  JSON_BODY_LIMIT: '10kb',
  URLENCODED_BODY_LIMIT: '10kb',
  PRODUCTION_DOMAIN: 'https://yourdomain.com'
};

function validateEnvironment() {
  const missing = [];

  // Check required environment variables
  for (const envVar of requiredEnvVars) {
    if (!process.env[envVar]) {
      missing.push(envVar);
    }
  }

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  // Set defaults for optional variables
  for (const [envVar, defaultValue] of Object.entries(optionalEnvVars)) {
    if (!process.env[envVar]) {
      process.env[envVar] = defaultValue.toString();
    }
  }

  // Validate numeric values
  const numericVars = ['PORT', 'RATE_LIMIT_WINDOW_MS', 'RATE_LIMIT_MAX_REQUESTS'];
  for (const envVar of numericVars) {
    if (process.env[envVar] && isNaN(parseInt(process.env[envVar]))) {
      console.warn(`Warning: ${envVar} should be a numeric value, got: ${process.env[envVar]}`);
    }
  }

  // Validate environment
  const validEnvironments = ['development', 'test', 'production'];
  if (!validEnvironments.includes(process.env.NODE_ENV)) {
    console.warn(`Warning: NODE_ENV should be one of [${validEnvironments.join(', ')}], got: ${process.env.NODE_ENV}`);
  }

  console.log('Environment validation completed successfully');
}

